/**
 * Expected values for the SSL Certificate Checker (/ssl).
 *
 * The tool shows what POST /api/ssl returned (backend/src/routes/ssl.js). In
 * contract tests that answer is generated by ./generator.ts and is the ground
 * truth; this file states how each part must appear. Nothing here imports
 * application code.
 *
 * Definitions
 *  - Request: `{ domain, port }`. `domain` is the host box, trimmed; the server
 *    reduces a URL to its host. `port` is the port box as an integer; an empty
 *    port box means 443. A port is a whole number from 1 to 65535: anything
 *    else is bad input and must be refused, not replaced by a default.
 *    A port written after the host (`host:8443`) is part of what the user asked
 *    for: it must be honoured or refused, never dropped.
 *  - Validation checks, in order, each green (passed) or red (failed):
 *      1. `<domain> resolves to <ip>`           passed when an address was found, else `N/A`
 *      2. `Server: <name>`                      passed unless the name is "Unknown"
 *      3. trust                                 `Certificate is trusted` when trusted. When not
 *                                               trusted the line gives the reason: `Self-signed
 *                                               certificate`, or `Missing intermediate certificates`
 *                                               when the chain has no intermediate. It must not
 *                                               blame the chain when the chain is complete.
 *      4. `Expires in <n> days` / `Certificate EXPIRED`
 *      5. `Hostname matches certificate` / `Hostname does NOT match`
 *      6. `HSTS enabled` / `HSTS not enabled`
 *  - Days Until Expiry card: the day count; red below 7 days (including
 *    expired), amber from 7 to 30, green above 30. These are the same limits
 *    the backend's grade uses (below 7: -40 points, up to 30: -15 points).
 *  - Security Grade card: the grade; green for A+ and A, amber for B, red for
 *    C, D and F.
 *  - Validity dates: calendar day in the browser's time zone, `Mon D, YYYY`.
 *  - Empty optional values: organisation shows an em dash; subject, issuer,
 *    serial and fingerprint show `N/A`.
 *  - Certificate chain roles: the first certificate is the Server certificate.
 *    A later certificate is a Root only when it is self-issued (subject equals
 *    issuer); every other one is an Intermediate.
 */

export const TIME_ZONE = process.env.E2E_TIMEZONE ?? 'America/New_York';
export const DAY_MS = 86_400_000;

export interface ChainCert {
  subject: string;
  subject_org: string;
  subject_country?: string;
  issuer: string;
  issuer_org: string;
  issuer_country?: string;
  serial_number?: string;
  not_before: string;
  not_after: string;
  san_names?: string[];
  signature_algorithm?: string;
  key_type: string;
  key_size: number | string;
  is_leaf?: boolean;
}

export interface SslAnswer {
  domain: string;
  valid: boolean;
  subject: string;
  subject_org: string;
  subject_country: string;
  issuer: string;
  issuer_org: string;
  issuer_country: string;
  serial_number: string;
  signature_algorithm: string;
  key_type: string;
  key_size: number | string;
  not_before: string;
  not_after: string;
  days_remaining: number;
  san_names: string[];
  protocol: string;
  fingerprint_sha256: string;
  chain: ChainCert[];
  grade: string;
  response_time_ms: number;
  dns: { ip: string | null; all_ips?: string[]; error?: string };
  server_type: { server: string; raw_server?: string; powered_by?: string; error?: string; security_headers: Record<string, string> };
  hostname_match: boolean;
  is_expired: boolean;
  has_intermediate: boolean;
  is_self_signed: boolean;
  is_trusted: boolean;
  security_headers: Record<string, string>;
}

// ─── Dates ───────────────────────────────────────────────────────────────────

const MONTHS = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
const two = (n: number) => String(n).padStart(2, '0');

/** `Feb  3 11:25:18 2027 GMT`, the form OpenSSL (and so the backend) writes certificate times in. */
export function certTime(ms: number): string {
  const d = new Date(ms);
  return `${MONTHS[d.getUTCMonth()]} ${String(d.getUTCDate()).padStart(2, ' ')} ${two(d.getUTCHours())}:${two(d.getUTCMinutes())}:${two(d.getUTCSeconds())} ${d.getUTCFullYear()} GMT`;
}

/** Milliseconds since the epoch for a certificate time; NaN when it is not one. */
export function parseCertTime(text: string): number {
  const m = /^([A-Z][a-z]{2})\s+(\d{1,2})\s+(\d{2}):(\d{2}):(\d{2})\s+(\d{4})\s+GMT$/.exec(text.trim());
  if (!m) return NaN;
  const month = MONTHS.indexOf(m[1]);
  if (month < 0) return NaN;
  return Date.UTC(Number(m[6]), month, Number(m[2]), Number(m[3]), Number(m[4]), Number(m[5]));
}

/** Calendar day of an instant in the browser's zone: `Feb 3, 2027`. */
export function localDay(ms: number): string {
  const parts = new Intl.DateTimeFormat('en-US', { timeZone: TIME_ZONE, year: 'numeric', month: 'numeric', day: 'numeric' }).formatToParts(new Date(ms));
  const part = (type: string) => Number(parts.find(p => p.type === type)!.value);
  return `${MONTHS[part('month') - 1]} ${part('day')}, ${part('year')}`;
}

export function validityDay(certTimeText: string): string {
  const ms = parseCertTime(certTimeText);
  return Number.isNaN(ms) ? 'N/A' : localDay(ms);
}

// ─── Rules of the backend, restated ───────────────────────────────────────────

/** Whole days from `nowMs` to the end of validity, rounded down; -1 when there is no end date. */
export function daysRemaining(notAfter: string, nowMs: number): number {
  const end = parseCertTime(notAfter);
  return Number.isNaN(end) ? -1 : Math.floor((end - nowMs) / DAY_MS);
}

/** Grade from the day count and two chain facts. */
export function grade(days: number, hasIntermediate: boolean, selfSigned: boolean): string {
  if (days < 0 || selfSigned) return 'F';
  let points = 100;
  if (days < 7) points -= 40;
  else if (days <= 30) points -= 15;
  if (!hasIntermediate) points -= 20;
  return points >= 90 ? 'A+' : points >= 80 ? 'A' : points >= 65 ? 'B' : points >= 50 ? 'C' : 'D';
}

/**
 * Does a certificate name cover `host`? RFC 6125: equal ignoring case, or a
 * `*.` name whose star stands for exactly one left-most label.
 */
export function nameCovers(certName: string, host: string): boolean {
  const name = certName.toLowerCase();
  const target = host.toLowerCase();
  if (name === target) return true;
  if (!name.startsWith('*.')) return false;
  const dot = target.indexOf('.');
  return dot > 0 && target.slice(dot + 1) === name.slice(2);
}

// ─── Colours ─────────────────────────────────────────────────────────────────

export type Tone = 'good' | 'warn' | 'bad';

export function daysTone(days: number): Tone {
  if (days < 7) return 'bad';
  return days <= 30 ? 'warn' : 'good';
}

export function gradeTone(value: string): Tone {
  if (value === 'A+' || value === 'A') return 'good';
  return value === 'B' ? 'warn' : 'bad';
}

/** `#65e2ba` → `rgb(101, 226, 186)`, the form the browser reports colours in. */
export function rgb(hex: string): string {
  let h = hex.trim().replace('#', '');
  if (h.length === 3) h = h.split('').map(c => c + c).join('');
  const channel = (i: number) => parseInt(h.slice(i, i + 2), 16);
  return `rgb(${channel(0)}, ${channel(2)}, ${channel(4)})`;
}

// ─── What the page must show ─────────────────────────────────────────────────

export interface CheckLine { ok: boolean; text: string }

export interface ChainRow {
  subject: string;
  role: string;
  org: string | null;
  valid: string;
  issuer: string;
  key: string | null;
}

export interface SslExpectation {
  /** Checks 1, 2, 4, 5, 6 (the trust line is separate: its wording depends on the cause). */
  dns: CheckLine;
  server: CheckLine;
  expiry: CheckLine;
  host: CheckLine;
  hsts: CheckLine;
  trustOk: boolean;
  /** Wording the trust line must have, or null when only "must not blame the chain" applies. */
  trustText: string | null;
  cards: [string, string][];
  daysTone: Tone;
  gradeTone: Tone;
  responseTime: string;
  details: [string, string][];
  sanTitle: string | null;
  sans: string[];
  chainTitle: string | null;
  chain: ChainRow[];
}

const orNA = (value: unknown) => (value === '' || value === null || value === undefined ? 'N/A' : String(value));
const orDash = (value: string) => (value === '' ? '—' : value);

export function chainRole(chain: ChainCert[], index: number): string {
  if (index === 0) return 'Server';
  const cert = chain[index];
  return cert.subject === cert.issuer ? 'Root' : 'Intermediate';
}

export function expectedSsl(a: SslAnswer): SslExpectation {
  let trustText: string | null = null;
  if (a.is_trusted) trustText = 'Certificate is trusted';
  else if (a.is_self_signed) trustText = 'Self-signed certificate';
  else if (!a.has_intermediate) trustText = 'Missing intermediate certificates';

  return {
    dns: { ok: Boolean(a.dns?.ip), text: `${a.domain} resolves to ${a.dns?.ip || 'N/A'}` },
    server: { ok: a.server_type.server !== 'Unknown', text: `Server: ${a.server_type.server}` },
    expiry: a.is_expired ? { ok: false, text: 'Certificate EXPIRED' } : { ok: true, text: `Expires in ${a.days_remaining} days` },
    host: a.hostname_match ? { ok: true, text: 'Hostname matches certificate' } : { ok: false, text: 'Hostname does NOT match' },
    hsts: a.security_headers?.hsts ? { ok: true, text: 'HSTS enabled' } : { ok: false, text: 'HSTS not enabled' },
    trustOk: a.is_trusted,
    trustText,
    cards: [
      ['Days Until Expiry', String(a.days_remaining)],
      ['Security Grade', a.grade],
      ['Protocol', a.protocol],
      ['Key Type', `${a.key_type} ${a.key_size}`],
    ],
    daysTone: daysTone(a.days_remaining),
    gradeTone: gradeTone(a.grade),
    responseTime: `${a.response_time_ms}ms`,
    details: [
      ['Subject', orNA(a.subject)],
      ['Organization', orDash(a.subject_org)],
      ['Issuer', orNA(a.issuer)],
      ['Issuer Org', orDash(a.issuer_org)],
      ['Serial Number', orNA(a.serial_number)],
      ['Valid From', validityDay(a.not_before)],
      ['Valid Until', validityDay(a.not_after)],
      ['Fingerprint (SHA-256)', orNA(a.fingerprint_sha256)],
    ],
    sanTitle: a.san_names.length ? `Subject Alternative Names (${a.san_names.length})` : null,
    sans: a.san_names,
    chainTitle: a.chain.length ? `Certificate Chain (${a.chain.length})` : null,
    chain: a.chain.map((cert, i) => ({
      subject: cert.subject,
      role: chainRole(a.chain, i),
      org: cert.subject_org ? cert.subject_org : null,
      valid: `${validityDay(cert.not_before)} — ${validityDay(cert.not_after)}`,
      issuer: cert.issuer,
      key: cert.key_type ? `${cert.key_type} ${cert.key_size}` : null,
    })),
  };
}

/** Text the "Copy Summary" button puts on the clipboard. */
export function expectedSummary(a: SslAnswer): string {
  return [
    `Domain: ${a.domain}`,
    `Issuer: ${orNA(a.issuer)}`,
    `Valid Until: ${orNA(a.not_after)}`,
    `Grade: ${orNA(a.grade)}`,
    `Protocol: ${orNA(a.protocol)}`,
  ].join('\n');
}

/**
 * One-row CSV export: a column per leaf field. Nested objects become columns
 * named with the path joined by spaces (`dns ip`); a list is written as JSON
 * text; null, booleans and numbers as their JSON literal.
 */
export function csvRecord(value: unknown): Record<string, string> {
  const out: Record<string, string> = {};
  const walk = (node: unknown, path: string[]) => {
    if (node !== null && typeof node === 'object' && !Array.isArray(node)) {
      for (const [key, child] of Object.entries(node as Record<string, unknown>)) walk(child, [...path, key]);
      return;
    }
    out[path.join(' ')] = Array.isArray(node) ? JSON.stringify(node) : String(node);
  };
  walk(value, []);
  return out;
}

// ─── Input ───────────────────────────────────────────────────────────────────

/** Host a typed value stands for (URL parts removed, lower case); '' when it names no host. */
export function hostOf(typed: string): string {
  const text = typed.trim();
  if (!text) return '';
  const withScheme = /^[a-z][a-z0-9+.-]*:\/\//i.test(text) ? text : `https://${text}`;
  try { return new URL(withScheme).hostname.toLowerCase(); } catch { return ''; }
}

/** Port written after the host in a typed value (`host:8443`, `https://host:8443/x`); null when there is none. */
export function portIn(typed: string): number | null {
  const text = typed.trim();
  const withScheme = /^[a-z][a-z0-9+.-]*:\/\//i.test(text) ? text : `https://${text}`;
  try {
    const port = new URL(withScheme).port;
    return port ? Number(port) : null;
  } catch { return null; }
}

/** Port box contents that are not a port number. */
export const BAD_PORTS: { typed: string; why: string }[] = [
  { typed: 'abc', why: 'not a number' },
  { typed: '0', why: 'zero is not a usable port' },
  { typed: '65536', why: 'above 65535' },
  { typed: '99999', why: 'above 65535' },
  { typed: '-443', why: 'negative' },
  { typed: '443abc', why: 'digits followed by text' },
  { typed: '44 3', why: 'space inside the number' },
  { typed: '443.5', why: 'fraction' },
  { typed: '4e2', why: 'exponent notation' },
  { typed: '0x1bb', why: 'hexadecimal' },
];
